function syncDraft(){draft.client=$('qClient').value.trim();draft.date=$('qDate').value;draft.document=$('qDocument').value.replace(/\D/g,'');draft.street=$('qStreet').value.trim();draft.number=$('qNumber').value.replace(/\D/g,'');draft.complement=$('qComplement').value.trim();draft.neighborhood=$('qNeighborhood').value.trim();draft.cep=$('qCep').value.replace(/\D/g,'');draft.address=[draft.street,draft.number,draft.neighborhood,draft.cep,draft.complement].filter(Boolean).join(', ');draft.contact=$('qContact').value.replace(/\D/g,'');draft.sellerUser=norm($('qSeller').value||currentUser?.username);draft.seller=sellerName(draft.sellerUser);draft.travel=Number($('qTravel').value||0);draft.discountPercent=Number($('qDiscount').value||0);draft.discountReason=$('qDiscountReason').value.trim()}
function quoteTotals(q){let p18=0,p4=0,cash=0,labor=0;for(const e of q.environments||[]){const c=calcEnvironment(e);if(c){p18+=c.p18;p4+=c.base4;cash+=c.cash;labor+=c.laborTotal}}for(const b of q.blinds||[]){const qty=Number(b.qty||1);p18+=Number(b.p18||0)*qty;p4+=Number(b.p4||0)*qty;cash+=Number(b.cash||0)*qty}for(const a of q.looseProducts||[]){const qty=Number(a.qty||1);p18+=Number(a.p18||0)*qty;p4+=Number(a.p4||0)*qty;cash+=Number(a.cash||0)*qty}const t=Number(q.travel||0);p18+=t*(1+db.priceConfig.terms.p18AddPct/100);p4+=t;cash+=t*(1-db.priceConfig.terms.cashDiscountPct/100);const d=Math.max(0,Math.min(100,Number(q.discountPercent||0)));return {p18:p18*(1-d/100),p4:p4*(1-d/100),cash:cash*(1-d/100),labor,discountPercent:d}}
